sys_script.script:
/**
 * ESR - Fire lifecycle events   (after / insert + update / order 1000)
 *
 * The notification seam. Exactly ONE event is queued per meaningful change -
 * the first matching branch wins and returns - so a single save never produces
 * duplicate emails.
 *
 *   insert                                    -> ticket.submitted
 *   assignment_group / assigned_to changed    -> ticket.assigned
 *   state -> 5                                -> ticket.resolved
 *   state 5 -> 3                              -> ticket.reopened
 *   state -> 6                                -> ticket.closed
 *   work_notes / comments changed, or any
 *   other state change                        -> ticket.updated
 *
 * This is an after rule: `current` is never modified here.
 */
;(function fireTicketLifecycleEvents(current, previous) {
    var ticketNumber = current.getValue('number') || ''
    var requester = current.getValue('requester') || ''
    var assignedTo = current.getValue('assigned_to') || ''
    var assignmentGroup = current.getValue('assignment_group') || ''

    /* ---------------------------------------------------------------
     * Insert - a new ticket was submitted
     * ------------------------------------------------------------- */
    if (current.operation() === 'insert') {
        gs.eventQueue('x_412993_employe_1.ticket.submitted', current, requester, ticketNumber)
        return
    }

    if (!previous) {
        return
    }

    var state = current.getValue('state')
    var previousState = previous.getValue('state')
    var stateChanged = state !== previousState

    /* ---------------------------------------------------------------
     * Assignment changed - group and/or person
     * ------------------------------------------------------------- */
    var groupChanged = assignmentGroup !== (previous.getValue('assignment_group') || '')
    var assigneeChanged = assignedTo !== (previous.getValue('assigned_to') || '')
    if (groupChanged || assigneeChanged) {
        gs.eventQueue('x_412993_employe_1.ticket.assigned', current, assignedTo, assignmentGroup)
        return
    }

    /* ---------------------------------------------------------------
     * Resolved
     * ------------------------------------------------------------- */
    if (stateChanged && state === '5') {
        gs.eventQueue(
            'x_412993_employe_1.ticket.resolved',
            current,
            requester,
            current.getDisplayValue('resolution_code') || ticketNumber
        )
        return
    }

    /* ---------------------------------------------------------------
     * Reopened (Resolved -> In Progress)
     * ------------------------------------------------------------- */
    if (stateChanged && previousState === '5' && state === '3') {
        gs.eventQueue('x_412993_employe_1.ticket.reopened', current, assignedTo, assignmentGroup)
        return
    }

    /* ---------------------------------------------------------------
     * Closed
     * ------------------------------------------------------------- */
    if (stateChanged && state === '6') {
        gs.eventQueue('x_412993_employe_1.ticket.closed', current, requester, ticketNumber)
        return
    }

    /* ---------------------------------------------------------------
     * Anything else worth telling the requester about: a new work note,
     * a new comment, or a state change not covered above
     * ------------------------------------------------------------- */
    var notesAdded = false
    try {
        notesAdded = current.work_notes.changes() || current.comments.changes()
    } catch (e) {
        notesAdded = false
    }

    if (notesAdded || stateChanged) {
        gs.eventQueue('x_412993_employe_1.ticket.updated', current, requester, ticketNumber)
    }
})(current, previous)
